    visited = [[False] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                # BFS to find all cells in this connected component
                cells = []
                queue = [(r, c)]
                visited[r][c] = True

                idx = 0
                while idx < len(queue):
                    curr_r, curr_c = queue[idx]
                    idx += 1
                    cells.append((curr_r, curr_c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Find the bounding box of this component
                min_r = min(cell[0] for cell in cells)
                max_r = max(cell[0] for cell in cells)
                min_c = min(cell[1] for cell in cells)
                max_c = max(cell[1] for cell in cells)

                # Fill the bounding box with '.' to make it a rectangle
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        grid[rr][cc] = '.'

    return '\n'.join(''.join(row) for row in grid)

