def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, e, i))

    # Kruskal's algorithm to find MST edges
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    # Build MST adjacency list
    mst_adj = [[] for _ in range(n + 1)]
    mst_idx = set()

    sorted_edges = sorted(edges, key=lambda x: x[2])

    for a, b, w, idx in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, w))
            mst_adj[b].append((a, w))
            mst_idx.add(idx)

    # BFS to compute depths and parent pointers
    LOG = 20
    up = [[0] * LOG for _ in range(n + 1)]
    max_w = [[0] * LOG for _ in range(n + 1)]
    depth = [0] * (n + 1)
    visited = {1}

    from collections import deque
    queue = deque([1])

    while queue:
        u = queue.popleft()
        for v, w in mst_adj[u]:
            if v not in visited:
                visited.add(v)
                depth[v] = depth[u] + 1
                up[v][0] = u
                max_w[v][0] = w
                queue.append(v)

    # Binary lifting precomputation
    for j in range(1, LOG):
        for i in range(1, n + 1):
            if up[i][j - 1] != 0:
                up[i][j] = up[up[i][j - 1]][j - 1]
                max_w[i][j] = max(max_w[i][j - 1], max_w[up[i][j - 1]][j - 1])
            else:
                up[i][j] = 0
                max_w[i][j] = 0

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        for j in range(LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                u = up[u][j]

        if u == v:
            return u

        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        return up[u][0]

    def max_on_path(u, v):
        lca = get_lca(u, v)
        result = 0

        for j in range(LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[lca]:
                result = max(result, max_w[u][j])
                u = up[u][j]

        for j in range(LOG - 1, -1, -1):
            if depth[v] - (1 << j) >= depth[lca]:
                result = max(result, max_w[v][j])
                v = up[v][j]

        return result

    # Process non-MST edges in original order
    results = []
    for a, b, w, idx in edges:
        if idx not in mst_idx:
            result = max_on_path(a, b)
            results.append(str(result))

    return '\n'.join(results)

