def find_initial_match(n, costs):
    """Create an initial matching greedily"""
    match = [-1] * n
    remaining = set(range(n))

    while len(remaining) > 0 and len(remaining) <= n - 1:
        i = random.choice(list(remaining))
        others = remaining - {i}
        if not others:
            remaining = remaining - {i}
            continue

        # Find minimum cost partner
        best_j = min(others, key=lambda j: costs[i][j])
        if match[i] == -1 and match[best_j] == -1:
            match[i] = best_j
            match[best_j] = i
            remaining -= {i, best_j}

    return match

def improve_match(n, costs, match):
    """Iteratively fix blocking pairs"""
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if match[i] == -1:
                continue
            for j in range(i+1, n):
                if match[j] == -1:
                    continue
                # Check if breaking their pairs results in better match
                pi = match[i]
                pj = match[j]
                if pi != j and pj != i:
                    if costs[i][j] < costs[i][pi] and costs[j][i] < costs[j][pj]:
                        # They prefer each other - reassign
                        match[i] = j
                        match[j] = i
                        changed = True
                        break
            if changed:
                break

    return match

def is_stable(n, costs, match):
    """Check if the matching is stable"""
    # All cities must be matched
    if any(m == -1 for m in match):
        return False

    # Check for blocking pairs
    for i in range(n):
        for j in range(i+1, n):
            pi = match[i]
            pj = match[j]
            # i and j are not matched to each other
            if pi != j and pj != i:
                # Both prefer each other over their current matches
                if costs[i][j] < costs[i][pi] and costs[j][i] < costs[j][pj]:
                    return False
    return True

