    if n == 1:
        return '0\n\n' if k == 0 else '-1'

    edges = []
    capital_edges = []
    other_edges = []

    for i in range(1, min(m, len(lines)) + 1):
        try:
            parts = lines[i].split()
            if len(parts) < 3:
                continue
            a, b, w = map(int, parts[:3])
            edges.append((i, a, b, w))
            if a == 1 or b == 1:
                capital_edges.append((i, a, b, w, True))
            else:
                other_edges.append((i, a, b, w, False))
        except:
            continue

    if len(capital_edges) < k:
        return '-1'

    # Initialize union-find
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1
            return True
        return False

    capital_edges.sort(key=lambda x: x[3])
    other_edges.sort(key=lambda x: x[3])

    results = []

    # Use exactly k capital edges that include vertex 1
    cap_used = 0
    for e in capital_edges:
        _, _, _, w, _ = e
        if cap_used == k:
            break
        u, v = e[1], e[2]
        if union(parent, u, v):
            results.append(e[0])
            cap_used += 1

    # Add other edges
    for e in other_edges:
        _, u, v, w, _ = e
        if union(parent, u, v):
            results.append(e[0])

    if len(results) != n - 1:
        return '-1'  # Not enough edges to connect everything

    # Final verification
    final_parent = list(range(n + 1))
    for idx in results:
        _, u, v, _, _ = edges[idx - 1]
        find(lambda x: (x if x != final_parent[x] else final_parent[x])(final_parent[x] if parent != idx else parent[u]))

    # Simplified check
    if len(results) != n - 1:
        return '-1'

    # Count components
    roots = [find(parent, i) for i in range(1, n + 1)]
    unique_roots = set(roots)

    if len(unique_roots) != 1:
        return '-1'

    # Output
    results_str = ' '.join(map(str, results))
    return f'{len(results)}\n{results_str}'

