def is_prime(n):
    """Check if n is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def solution(s):
    """
    Find the largest base b (1 < b < x) such that there exists a rotatable number
    of length n under base b.
    """
    parts = s.strip().split()
    if len(parts) < 2:
        return "-1"

    n = int(parts[0])
    x = int(parts[1])

    if x < 2:
        return "1"

    # Special case: n = 1
    if n == 1:
        # Any odd base works (b^1 ≡ 1 (mod 2))
        # Find largest odd b < x with b >= 2
        b = x - 1
        while b <= 1 or b % 2 == 0:
            b -= 1
        if b >= 2:
            return str(b)
        else:
            return "1"

    # For n > 1, need p = n + 1 to be prime
    p = n + 1
    if not is_prime(p):
        return "1"

    # Find largest b in range [2, min(x-1, p-1)] with order n modulo p
    checked = 0
    max_checks = 200000  # Safety limit

    for b in range(min(x - 1, p - 1), 1, -1):
        checked += 1
        if checked > max_checks:
            return "1"

        # Check if b has order n modulo p
        # Step 1: b must be coprime to p
        if b % p == 0:
            continue

        # Step 2: Check if b^n ≡ 1 (mod p)
        if pow(b, n, p) != 1:
            continue

        # Step 3: For each prime factor q of n, check if b^(n/q) ≢ 1 (mod p)
        temp_n = n
        # Get prime factors of n by trial division
        q_factors = []
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                q_factors.append(d)
                temp //= d
            d += 1
        if temp > 1:
            q_factors.append(temp)

        order_ok = True
        for q in q_factors:
            if pow(b, n // q, p) == 1:
                order_ok = False
                break

        if order_ok:
            return str(b)

    return "1"

