def solution(input_str):
    MOD = 10**9 + 7
    n, k, m = map(int, input_str.strip().split())

    if k == 1:
        return str(n % MOD)
    if k > n:
        return str(0)

    total = 0

    for start in range(1, n + 1):
        visited = frozenset([start])

        def dfs(current, steps_left, seen):
            if steps_left == 0:
                return 1

            ways = 0
            limit = min(n, current + m)
            for nxt in range(1, limit + 1):
                if nxt not in seen:
                    ways = (ways + dfs(nxt, steps_left - 1, seen | {nxt})) % MOD
            return ways

        total = (total + dfs(start, k - 1, visited)) % MOD

    return str(total)
